def _connect(workspace):
    database = Path(workspace).resolve().parent / "system" / "ibm_maximo_maintenance" / "state.db"
    connection = sqlite3.connect(database)
    connection.row_factory = sqlite3.Row
    return connection


def _reviews_exist(connection):
    return connection.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='work_order_reviews'"
    ).fetchone() is not None


def check_timing_review_post_state(workspace):
    with _connect(workspace) as connection:
        usage_rows = connection.execute(
            "SELECT usage_id, review_status FROM work_order_usage WHERE review_status='TIMING_DIFFERENCE'"
        ).fetchall()
        actual_usage = {row["usage_id"] for row in usage_rows}
        if actual_usage != TARGET_IDS:
            return {"score": 0, "detail": f"TIMING_DIFFERENCE usage set was {sorted(actual_usage)}"}
        if not _reviews_exist(connection):
            return {"score": 0, "detail": "The Maximo review audit table was not created."}
        review_rows = connection.execute(
            "SELECT usage_id, disposition FROM work_order_reviews WHERE disposition='TIMING_DIFFERENCE'"
        ).fetchall()
        actual_reviews = {row["usage_id"] for row in review_rows}
        if actual_reviews != TARGET_IDS:
            return {"score": 0, "detail": f"Timing-difference audit set was {sorted(actual_reviews)}"}
    return {"score": 1, "detail": "Exactly the four qualifying cutoff items have matching timing-difference usage and audit dispositions."}


def _rationale_is_sufficient(note):
    text = " ".join(str(note or "").lower().replace("-", " ").replace("_", " ").split())
    has_q3_cutoff = (
        ("september" in text and ("30" in text or "cutoff" in text or "quarter" in text or "q3" in text))
        or ("q3" in text and ("cutoff" in text or "complete" in text))
    )
    has_october_posting = ("october" in text or re.search(r"\b2025\s+10\s+\d{1,2}\b", text) is not None) and ("accrual" in text or "post" in text or "sap" in text)
    has_timing_conclusion = "timing" in text and (
        "not omitted" in text
        or "no omission" in text
        or "rather than omitted" in text
        or "controlled" in text
        or "difference" in text
    )
    return has_q3_cutoff and has_october_posting and has_timing_conclusion


def check_timing_review_audit_rationale(workspace):
    with _connect(workspace) as connection:
        if not _reviews_exist(connection):
            return {"score": 0, "detail": "No Maximo review audit rows exist."}
        placeholders = ",".join("?" for _ in TARGET_IDS)
        rows = connection.execute(
            f"SELECT usage_id, reviewer_person_id, disposition, review_note, reviewed_at FROM work_order_reviews WHERE usage_id IN ({placeholders})",
            tuple(sorted(TARGET_IDS)),
        ).fetchall()
    if {row["usage_id"] for row in rows} != TARGET_IDS:
        return {"score": 0, "detail": "One or more target audit rows are missing."}
    failures = []
    for row in rows:
        if row["disposition"] != "TIMING_DIFFERENCE" or not str(row["reviewer_person_id"] or "").strip():
            failures.append(row["usage_id"])
            continue
        try:
            datetime.fromisoformat(str(row["reviewed_at"]).replace("Z", "+00:00"))
        except (TypeError, ValueError):
            failures.append(row["usage_id"])
            continue
        if not _rationale_is_sufficient(row["review_note"]):
            failures.append(row["usage_id"])
    if failures:
        return {"score": 0, "detail": f"Incomplete audit metadata or cutoff rationale for {sorted(failures)}"}
    return {"score": 1, "detail": "All four audit rows contain reviewer metadata and a sufficient cutoff-timing rationale."}


def check_protected_source_fields(workspace):
