        "completed_order_count, labor_minutes, work_status, completion_date, sap_accrual_posting_date, "
        "is_duplicate, duplicate_of_usage_id, source_record_key"
    )
    ids = tuple(sorted(PROTECTED_USAGE))
    placeholders = ",".join("?" for _ in ids)
    with _connect(workspace) as connection:
        rows = connection.execute(
            f"SELECT usage_id, {columns} FROM work_order_usage WHERE usage_id IN ({placeholders})",
            ids,
        ).fetchall()
        history_rows = connection.execute(
            f"SELECT status_event_id, usage_id, from_status, to_status, event_timestamp, changed_by_person_id, change_reason_code, source_event_key "
            f"FROM work_order_status_history WHERE usage_id IN ({placeholders})",
            ids,
        ).fetchall()
    actual_usage = {row["usage_id"]: tuple(row[column.strip()] for column in columns.split(",")) for row in rows}
    if actual_usage != PROTECTED_USAGE:
        changed = sorted(set(PROTECTED_USAGE) | set(actual_usage))
        return {"score": 0, "detail": f"A protected source field or record changed in the reviewed population: {changed}"}
    actual_history = {tuple(row) for row in history_rows}
    if actual_history != PROTECTED_HISTORY:
        return {"score": 0, "detail": "Protected status-history evidence was changed, removed, or added."}
    return {"score": 1, "detail": "Protected usage fields and status-history evidence remain unchanged."}


def check_other_exception_treatments(workspace):
