    with _connect(workspace) as connection:
        rows = connection.execute(
            f"SELECT usage_id, review_status FROM work_order_usage WHERE usage_id IN ({placeholders})",
            ids,
        ).fetchall()
        actual = {row["usage_id"]: row["review_status"] for row in rows}
        if actual != EXCEPTION_STATUSES:
            return {"score": 0, "detail": f"Established exception treatments changed: {actual}"}
        if _reviews_exist(connection):
            review_count = connection.execute(
                f"SELECT COUNT(*) FROM work_order_reviews WHERE usage_id IN ({placeholders})",
                ids,
            ).fetchone()[0]
            if review_count:
                return {"score": 0, "detail": "An audit review was written to a protected exception record."}
    return {"score": 1, "detail": "Canceled, reopened, duplicate, and orphan exception treatments remain untouched."}
